$ErrorActionPreference = 'Stop'
$out = 'C:\nq-out'; $data = 'C:\nq-data'; $password = 'SandboxTest-42!'
$results = [ordered]@{ steps = [ordered]@{}; metrics = [ordered]@{} }
function Log($message) { "$(Get-Date -Format o) $message" | Add-Content "$out\log.txt" }
function Step($name, [scriptblock]$action) { Log "START $name"; try { & $action; $results.steps[$name] = @{ ok = $true }; Log "OK $name" } catch { $results.steps[$name] = @{ ok = $false; error = $_.Exception.ToString() }; Log "FEHLER $name : $_" } }
function Assert($condition, $message) { if (-not $condition) { throw $message } }
function Size($dir) { if (Test-Path $dir) { return [long]((Get-ChildItem $dir -Force -Recurse -File -ErrorAction SilentlyContinue | Measure-Object Length -Sum).Sum) }; return 0 }
function Status($uri, $auth) { try { $headers = @{}; if ($auth) { $headers.Authorization = $auth }; return [int](Invoke-WebRequest -UseBasicParsing -Uri $uri -Headers $headers -TimeoutSec 10).StatusCode } catch { if ($_.Exception.Response) { return [int]$_.Exception.Response.StatusCode }; throw } }
$exe = Join-Path $env:LOCALAPPDATA 'Programs\NextQuest\NextQuest.exe'; $installDir = Split-Path $exe
$auth = 'Basic ' + [Convert]::ToBase64String([Text.Encoding]::UTF8.GetBytes("nextquest:$password"))
try {
 Step install { $sw = [Diagnostics.Stopwatch]::StartNew(); $p = Start-Process 'C:\nq-in\setup.exe' -ArgumentList '/S' -Wait -PassThru; $sw.Stop(); $results.metrics.installSeconds = $sw.Elapsed.TotalSeconds; Assert ($p.ExitCode -eq 0) "Setup exit $($p.ExitCode)"; Assert (Test-Path $exe) "Executable fehlt: $exe"; Assert ((Test-Path "$env:APPDATA\Microsoft\Windows\Start Menu\Programs\NextQuest.lnk") -or (Test-Path "$env:ProgramData\Microsoft\Windows\Start Menu\Programs\NextQuest.lnk")) 'Startmenü-Verknüpfung fehlt'; Assert ((Test-Path "$env:USERPROFILE\Desktop\NextQuest.lnk") -or (Test-Path "$env:PUBLIC\Desktop\NextQuest.lnk")) 'Desktop-Verknüpfung fehlt' }
 Step start { $env:NEXTQUEST_DATA_DIR = $data; $env:NEXTQUEST_PASSWORD = $password; Start-Process $exe -ArgumentList '--screenshot=C:\nq-out\app.png','--qr-screenshot=C:\nq-out\qr.png' | Out-Null; $deadline = (Get-Date).AddMinutes(3); $script:port = $null; while ((Get-Date) -lt $deadline -and -not $script:port) { foreach ($candidate in 7918..7928) { try { if ((Status "http://127.0.0.1:$candidate/api/health" $null) -eq 200 -and (Status "http://127.0.0.1:$candidate/api/version" $auth) -eq 200) { $script:port = $candidate; break } } catch {} }; if (-not $script:port) { Start-Sleep -Seconds 2 } }; Assert $script:port 'Server nicht erreichbar'; $results.metrics.port = $script:port }
 Step api { Assert $script:port 'Kein Port'; $base = "http://127.0.0.1:$script:port"; Assert ((Status "$base/api/version" $null) -eq 401) 'Ohne Passwort kein 401'; $version = Invoke-RestMethod "$base/api/version" -Headers @{ Authorization = $auth }; Assert ($version.runtime -eq 'windows') "Runtime: $($version.runtime)"; $ip = (Get-NetIPAddress -AddressFamily IPv4 | Where-Object { $_.IPAddress -notmatch '^(127\.|169\.254\.)' -and $_.PrefixOrigin -ne 'WellKnown' } | Select-Object -First 1).IPAddress; Assert $ip 'Keine LAN-IP'; $lan = "http://${ip}:$script:port"; Assert ((Status "$lan/api/version" $null) -eq 401) 'LAN ohne Passwort kein 401'; Assert ((Status "$lan/api/version" $auth) -eq 200) 'LAN mit Passwort kein 200'; $results.metrics.lanIp = $ip; Invoke-RestMethod "$base/api/demo" -Method Post -Headers @{ Authorization = $auth } -ContentType 'application/json' -Body '{}' | Out-Null; $library = Invoke-RestMethod "$base/api/library" -Headers @{ Authorization = $auth }; Assert ($library.games.Count -gt 0) 'Bibliothek leer' }
 Step screenshots { $deadline = (Get-Date).AddSeconds(30); while ((-not (Test-Path "$out\app.png") -or -not (Test-Path "$out\qr.png")) -and (Get-Date) -lt $deadline) { Start-Sleep 1 }; Assert ((Test-Path "$out\app.png") -and (Test-Path "$out\qr.png")) 'Screenshot fehlt' }
 Step resources { $before = @(Get-Process NextQuest,electron,node -ErrorAction SilentlyContinue); $cpuBefore = [double](($before | Measure-Object CPU -Sum).Sum); Start-Sleep 30; $procs = @(Get-Process NextQuest,electron,node -ErrorAction SilentlyContinue); Assert ($procs.Count -gt 0) 'Keine Prozesse'; $results.metrics.workingSetBytes = [long](($procs | Measure-Object WorkingSet64 -Sum).Sum); $results.metrics.cpuSecondsDuring30s = [Math]::Max(0, [double](($procs | Measure-Object CPU -Sum).Sum) - $cpuBefore); $results.metrics.cpuPercentOneCore = $results.metrics.cpuSecondsDuring30s / 30 * 100; $results.metrics.installBytes = Size $installDir; $results.metrics.dataBytes = Size $data }
 Step quit { Start-Process $exe -ArgumentList '--quit' -Wait; $deadline = (Get-Date).AddSeconds(15); do { $procs = @(Get-Process NextQuest,electron,node -ErrorAction SilentlyContinue); if ($procs.Count -eq 0) { break }; Start-Sleep 1 } while ((Get-Date) -lt $deadline); Assert ($procs.Count -eq 0) 'Prozesse laufen noch' }
 Step uninstall { $uninstaller = Join-Path $installDir 'Uninstall NextQuest.exe'; Assert (Test-Path $uninstaller) 'Uninstaller fehlt'; $p = Start-Process $uninstaller -ArgumentList '/S' -PassThru -Wait; Assert ($p.ExitCode -eq 0) "Uninstall exit $($p.ExitCode)"; Assert (-not (Test-Path $exe)) 'Programm vorhanden'; Assert (Test-Path $data) 'Datenordner fehlt' }
} catch { $results.steps.fatal = @{ ok = $false; error = $_.Exception.ToString() }; Log "FATAL $_" } finally {
 $ok = @($results.steps.Values | Where-Object { -not $_.ok }).Count -eq 0
 $results | ConvertTo-Json -Depth 10 | Set-Content "$out\results.json" -Encoding UTF8
 @{ ok = $ok } | ConvertTo-Json | Set-Content "$out\done.json" -Encoding UTF8
 shutdown.exe /s /t 5
}
